using System.Text;
using FinanceTracker.Generated.Shared;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.Text;

namespace FinanceTracker.Generated.Enums;

/// <summary>
/// Adds the <c>InjectionCategoryType</c> enum, which says which registration method registers a class.
/// </summary>
[Generator]
public class InjectionCategoryTypeEnumGenerator : IIncrementalGenerator
{
    /// <summary>
    /// The enum's source.
    /// </summary>
    private const string EnumSourceCode = $$"""
                                            // <auto-generated/>
                                            namespace {{SourceGeneratorConstants.GeneratedNamespace}}.Enums
                                            {
                                                /// <summary>
                                                /// Which registration method registers a class.
                                                /// </summary>
                                                internal enum {{SourceGeneratorConstants.InjectionCategoryEnumName}}
                                                {
                                                    /// <summary>
                                                    /// <c>AddFinanceTrackerServices</c>, the app's own services.
                                                    /// </summary>
                                                    Service,
                                                    /// <summary>
                                                    /// <c>AddFinanceTrackerValidators</c>, request validators.
                                                    /// </summary>
                                                    Validator,
                                                    /// <summary>
                                                    /// <c>AddFinanceTrackerExternalServices</c>, external clients.
                                                    /// </summary>
                                                    External
                                                }
                                            }
                                            """;

    /// <inheritdoc/>
    public void Initialize(IncrementalGeneratorInitializationContext context) =>
        context.RegisterPostInitializationOutput(ctx => ctx.AddSource(
            $"{SourceGeneratorConstants.InjectionCategoryEnumName}Enum.g.cs",
            SourceText.From(EnumSourceCode, Encoding.UTF8)));
}
